with `did:key` and `did:webvh`.","type":"string","minLength":16,"pattern":"^(z[1-9A-HJ-NP-Za-km-z]+|u[A-Za-z0-9_-]+)\$","examples":["zQmbWqxBEKC3P8tqsKc98xmWNzrzDtRLMiMPL8wBuTGsMnR"]},"Introductions":{"title":"Introductions","description":"Who may ask the community to introduce them to this member. `anyone`: any active member who can find the entry. `groups`: only members who share a community group with them. `connections`: only members holding an attributed, in-force verified relationship with them. `off`: nobody. A refused introduction is never reported to its sender.","type":"string","enum":["anyone","groups","connections","off"]},"Discoverability":{"title":"Discoverability","description":"The member\'s three discoverability decisions, made separately.","type":"object","additionalProperties":false,"required":["listing","search","external"],"properties":{"listing":{"\$ref":"#/\$defs/Listing"},"search":{"type":"string","enum":["byName","exactNickname","off"],"description":"What a member\'s search may match. `byName`: `displayName` or `nickname`. `exactNickname`: only an exact `nickname`. `off`: nothing. A DID is never a search key for a non-administrator, whatever this says."},"external":{"type":"boolean","description":"Whether the member publishes a public card — the fields whose visibility is `public`, signed by the member — through the community\'s trust registry. A second consent, separate from registry-publication consent (`publishConsent`), which it requires. A community that cannot yet publish external cards refuses `true` with `notAvailable`."}}},"Listing":{"title":"Listing","description":"Whether members can find the entry. `listed`: it appears when members browse. `findable`: it does not appear when browsing, but a search that matches it under `search` returns it. `hidden`: no member finds it by browsing or searching; administrators still see it, and members who share a group that shows its members see it in that group\'s member list.","type":"string","e